const triggerData = $('Telegram Trigger').first().json;
let dbData = $('Supabase: Get Session').first().json || {};

if (Array.isArray(dbData)) dbData = dbData[0] || {};

let chatId = triggerData.message?.chat?.id?.toString() || triggerData.callback_query?.message?.chat?.id?.toString();
let msg = triggerData.message?.text || triggerData.callback_query?.data || "";

if (!chatId) return { json: { stop: true } };

const recordExists = !!(dbData && dbData.chat_id);

let currentState = dbData.state || "START";
let mode = dbData.mode || "";
let p1 = dbData.p1_data || "";
let p2 = dbData.p2_data || "";

let reply = "I'm processing that... one moment.";
let nextState = currentState;
let routeChat = false;
let isComplete = false;

if (msg.toLowerCase().includes("/start")) {
  currentState = "START";
}

switch (currentState) {
  case "START":
    reply = "Welcome! Choose: 🔮 <b>Chart</b> or 💞 <b>Synastry</b>?";
    nextState = "AWAITING_CHOICE";
    break;

  case "AWAITING_CHOICE":
    if (msg.toLowerCase().includes("natal") || msg.toLowerCase().includes("chart")) {
      mode = "natal";
      reply = "🔮 <b>Personal Chart Mode</b>\nSend your birth data (City, DD/MM/YYYY HH:mm):";
      nextState = "AWAITING_NATAL_DATA";
    } else if (msg.toLowerCase().includes("synastry")) {
      mode = "synastry";
      reply = "💞 <b>Synastry Mode</b>\nSend Person 1 data (City, DD/MM/YYYY HH:mm):";
      nextState = "AWAITING_P1";
    } else {
      reply = "Please choose: 🔮 <b>Chart</b> or 💞 <b>Synastry</b>?";
      nextState = "AWAITING_CHOICE";
    }
    break;

  case "AWAITING_NATAL_DATA":
    p1 = msg;
    reply = "✨ Calculating your personal natal alignment... ✨";
    nextState = "CHAT";
    isComplete = true;
    break;

  case "AWAITING_P1":
    p1 = msg;
    reply = "✅ Got Person 1. Now send <b>Person 2 data</b> (City, DD/MM/YYYY HH:mm):";
    nextState = "AWAITING_P2";
    break;

  case "AWAITING_P2":
    p2 = msg;
    reply = "🌌 Comparing soul dynamics... ✨";
    nextState = "CHAT";
    isComplete = true;
    break;

  case "CHAT":
    routeChat = true;
    nextState = "CHAT";
    break;

  default:
    reply = "Welcome! Choose: 🔮 <b>Chart</b> or 💞 <b>Synastry</b>?";
    nextState = "AWAITING_CHOICE";
    break;
}

return {
  json: {
    chatId,
    reply,
    nextState,
    recordExists,
    mode,
    p1_data: p1,
    p2_data: p2,
    routeChat,
    isComplete,
    userQuery: msg
  }
};

const engineData = $('Logic Engine').item.json;
const p1Raw = engineData.p1_data || "";
const p2Raw = engineData.p2_data || "";

function parseInput(str, personName) {
  const parts = str.split(',');
  const city = parts[0] ? parts[0].trim() : "Tbilisi";
  const timedata = parts[1] ? parts[1].trim().split(' ') : [];
  const datePart = timedata[0] || "19/05/2026";
  const timePart = timedata[1] || "12:00";

  const [day, month, year] = datePart.split('/').map(Number);
  const [hour, min] = timePart.split(':').map(Number);

  return { person: personName, city, day: day||19, month: month||5, year: year||2026, hour: hour||12, min: min||0 };
}

const items = [];
if (p1Raw) items.push({ json: parseInput(p1Raw, "p1") });
if (p2Raw) items.push({ json: parseInput(p2Raw, "p2") });

return items;

const rawSnippets = $json.snippets || [];
let processedRagContext = "No additional manuscript contexts retrieved.";

if (Array.isArray(rawSnippets) && rawSnippets.length > 0) {
  processedRagContext = rawSnippets.join('\n');
} else if (typeof rawSnippets === 'string') {
  processedRagContext = rawSnippets;
}

return {
  json: {
    processedRagContext
  }
};

try {
    // Looks for 'output' or fallback 'text' from the incoming node data
    let rawOutput = $input.first().json.output || $input.first().json.text || "";
    return [{ json: { text: rawOutput } }];
} catch (e) {
    return [{ json: { text: "⚠️ <b>System Error:</b> Breakdown framing contextual response data." } }];
}

// 1. Fetch data safely
const logicEngine = $('Logic Engine').first()?.json || {};

// If we are just chatting, skip deep lookups to prevent execution crashes
if (logicEngine.routeChat && !logicEngine.isComplete) {
  return [{
    json: {
      apiUrl: "https://json.astrologyapi.com/v1/western_horoscope",
      payload: {},
      isChatRoute: true
    }
  }];
}

let parsedIntake = [];
let geoCoordinates = [];
let tzOffsets = [];

// Use try/catch blocks to prevent crashes if nodes weren't executed
try { parsedIntake = $('Parse Intake Data').all().map(item => item.json || {}); } catch(e) {}
try { geoCoordinates = $('Get Coordinates').all().map(item => item.json || {}); } catch(e) {}
try { tzOffsets = $('Get Timezone Offset').all().map(item => item.json || {}); } catch(e) {}

const isSynastry = !!logicEngine.p2_data;
const targetUrl = isSynastry 
  ? 'https://json.astrologyapi.com/v1/synastry_horoscope' 
  : 'https://json.astrologyapi.com/v1/western_horoscope';

// 2. Robust Parser
function getPersonData(index) {
  const intake = parsedIntake[index] || {};
  const geo = geoCoordinates[index] || {};
  const tz = tzOffsets[index] || {};

  return {
    day: parseInt(intake.day, 10) || 19,
    month: parseInt(intake.month, 10) || 5,
    year: parseInt(intake.year, 10) || 2026,
    hour: parseInt(intake.hour, 10) || 12,
    min: parseInt(intake.min, 10) || 0,
    latitude: parseFloat(geo.lat || geo[0]?.lat || 41.7151),
    longitude: parseFloat(geo.lon || geo.lng || geo[0]?.lon || 44.8271),
    timezone: parseFloat(tz.gmtOffset || 4.0)
  };
}

// 3. Construct Payload (Adjusted for flat structure)
let finalPayload = {};

if (isSynastry) {
  const p1 = getPersonData(0);
  const p2 = getPersonData(1);

  finalPayload = {
    p_day: p1.day, p_month: p1.month, p_year: p1.year,
    p_hour: p1.hour, p_min: p1.min, p_lat: p1.latitude, 
    p_lon: p1.longitude, p_tzone: p1.timezone,

    s_day: p2.day, s_month: p2.month, s_year: p2.year,
    s_hour: p2.hour, s_min: p2.min, s_lat: p2.latitude, 
    s_lon: p2.longitude, s_tzone: p2.timezone
  };
} else {
  const p1 = getPersonData(0);
  finalPayload = {
    day: p1.day, month: p1.month, year: p1.year,
    hour: p1.hour, min: p1.min, lat: p1.latitude, 
    lon: p1.longitude, tzone: p1.timezone
  };
}

// 4. Return
return [{
  json: {
    apiUrl: targetUrl,
    payload: finalPayload,
    isChatRoute: false,
    chatId: $('Record Exists?').first().json.chatId
  }
}];

const logicEngineData = $('Logic Engine').first()?.json || {};
const userPrompt = logicEngineData.userQuery || "Analyze chart"; 

let diagnosticStr = "NO_LIVE_CHART_CALCULATED";
let processedRagContext = "No additional manuscript contexts retrieved.";

// 1. Check for LIVE calculations safely using try/catch
try {
  const apiData = $('Astrology API Engine').first()?.json;

  // Only parse if the node actually returned real planetary positions
  if (apiData && (apiData.planets || apiData.first)) {
    diagnosticStr = parseAstrologyPayload(apiData);
  }
} catch (e) {
  // Node wasn't executed or was bypassed, diagnosticStr remains 'NO_LIVE_CHART_CALCULATED'
}

// 2. Try to fetch RAG Context cleanly
try {
  const ragNode = $('Final Similarity Filter').first()?.json;
  if (ragNode && ragNode.processedRagContext) {
    processedRagContext = ragNode.processedRagContext;
  }
} catch (e) {}

// Helper function to stringify planetary data cleanly
function parseAstrologyPayload(apiData) {
  const formatPlanets = (planetList, label) => {
    return planetList.map(p => `${label}: ${p.name} in ${p.sign} (House ${p.house})`).join(', ');
  };
  if (apiData.first && apiData.second) {
    let str = `${formatPlanets(apiData.first, "Person 1")} | ${formatPlanets(apiData.second, "Person 2")}`;
    if (apiData.aspects) {
      const aspects = apiData.aspects.map(a => `${a.aspecting_planet} ${a.type} ${a.aspected_planet} (Orb: ${a.orb}°)`).join(', ');
      str += ` | Aspects: ${aspects}`;
    }
    return str;
  } else if (apiData.planets) {
    return apiData.planets.map(p => `${p.name} in ${p.sign} (House ${p.house})`).join(', ');
  }
  return "NO_LIVE_CHART_CALCULATED";
}

return {
  json: {
    chatInput: userPrompt,
    driveContext: processedRagContext,
    astrologyData: diagnosticStr,
    isCalculationRoute: (diagnosticStr !== "NO_LIVE_CHART_CALCULATED"),
    sessionId :$('Record Exists?').first().json.chatId 
  }
};

let isSynastryRoute = false;
let natalPlacements = [];
let p1Placements = [];
let p2Placements = [];
let consolidatedAspects = [];
let formattedText = "NO_LIVE_CALCULATION_THIS_TURN_USE_HISTORY_MEMORY";
let activeSessionId = "";
let activeChatInput = "";

// Native, safe n8n global helper input retrieval
const items = $input.all();

if (items && items.length > 0) {
  items.forEach(item => {
    const data = item.json;
    if (!data) return;

    // Safely trap passthrough parameters
    if (data.sessionId) activeSessionId = data.sessionId;
    if (data.chatInput) activeChatInput = data.chatInput;
    if (!activeSessionId && activeChatInput) activeSessionId = activeChatInput;

    // --- 1. PARSE OUT RAW PAYLOAD PAYLOAD STRINGS ---
    if (data.astrologyData && typeof data.astrologyData === 'string') {
      if (data.astrologyData.includes('Person 2:') || data.astrologyData.includes('P2 ')) {
        isSynastryRoute = true;
      }

      let parts = data.astrologyData.split('|');
      parts.forEach(part => {
        let elements = part.split(',').map(e => e.trim());
        elements.forEach(el => {
          if (el.startsWith('Person 1:') || el.startsWith('P1 ')) {
            p1Placements.push(`• ${el.replace(/Person 1:\s*|P1\s*/i, '')}`);
          } else if (el.startsWith('Person 2:') || el.startsWith('P2 ')) {
            p2Placements.push(`• ${el.replace(/Person 2:\s*|P2\s*/i, '')}`);
          } else if (el.length > 0) {
            natalPlacements.push(`• ${el}`);
          }
        });
      });
    }

    // --- 2. BACKUP: SCENARIO ARRAY PROCESSING ---
    else if ((data.first && data.first.length > 0) || (data.second && data.second.length > 0)) {
      isSynastryRoute = true;
      if (Array.isArray(data.first)) {
        data.first.forEach(p => p1Placements.push(`• ${p.name}: ${p.sign} (${p.house}H)`));
      }
      if (Array.isArray(data.second)) {
        data.second.forEach(p => p2Placements.push(`• ${p.name}: ${p.sign} (${p.house}H)`));
      }
    }
    else if (data.planets && Array.isArray(data.planets)) {
      data.planets.forEach(p => natalPlacements.push(`• ${p.name}: ${p.sign} (${p.house}H)`));
    }

    // --- 3. CAPTURE AUTOMATED ASPECTS (IF AVAILABLE) ---
    let targets = data.aspects || data;
    if (Array.isArray(targets)) {
      targets.forEach(a => {
        if (a.aspecting_planet && a.aspected_planet) {
          let orbVal = parseFloat(a.orb) || 0;
          consolidatedAspects.push({
            string: `<code>${a.aspecting_planet} ${a.type} ${a.aspected_planet} (Orb: ${orbVal.toFixed(2)}°)</code>`,
            orb: orbVal
          });
        }
      });
    }
  });

  // Sort aspects by exact mathematical closeness
  consolidatedAspects.sort((a, b) => a.orb - b.orb);
  let aspectStrings = consolidatedAspects.map(a => a.string);

  // --- 4. ASSEMBLE STRUCTURAL WORKFLOW OUTPUT ---
  let output = `[LIVE DATA PACKET RATIFIED]\n`;
  output += `ROUTE_DETECTED: ${isSynastryRoute ? 'SYNASTRY_COMPATIBILITY' : 'NATAL_BLUEPRINT'}\n\n`;

  if (isSynastryRoute) {
    output += `### PROFILE 1 CORE PLACEMENTS (HOME BASELINE)\n` + (p1Placements.join('\n') || 'No P1 Placements Found') + `\n\n`;
    output += `### PROFILE 2 CORE PLACEMENTS (INCOMING ENERGY)\n` + (p2Placements.join('\n') || 'No P2 Placements Found') + `\n\n`;
    output += `### CRITICAL CROSS-CHART GEOMETRIC INTERSECTIONS (SORTED BY URGENCY)\n`;
    output += aspectStrings.length > 0 ? aspectStrings.join('\n') : 'No tight inter-chart alignments under 4.0°. Focus heavily on the House Overlays above.';
  } else {
    output += `### INDIVIDUAL NATAL PLACEMENTS\n` + (natalPlacements.join('\n') || 'No Natal Placements Found') + `\n\n`;
    output += `### INTERNAL ASPECT GEOMETRY (SORTED BY FORCE INTENSITY)\n`;
    output += aspectStrings.length > 0 ? aspectStrings.join('\n') : 'No major planetary aspects active.';
  }

  formattedText = output;
}

return [
  {
    json: {
      sessionId: activeSessionId,
      chatInput: activeChatInput,
      sanitizedAstrologyData: formattedText
    }
  }
];
